module.exports = "import React from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\nimport {\n  EuiInMemoryTable,\n  EuiLink,\n  EuiHealth,\n} from '../../../../../src/components';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst store = createDataStore();\n\nexport const Table = () => {\n  const columns = [\n    {\n      field: 'firstName',\n      name: 'First Name',\n      sortable: true,\n      truncateText: true,\n    },\n    {\n      field: 'lastName',\n      name: 'Last Name',\n      truncateText: true,\n    },\n    {\n      field: 'github',\n      name: 'Github',\n      render: username => (\n        <EuiLink href={`https://github.com/${username}`} target=\"_blank\">\n          {username}\n        </EuiLink>\n      ),\n    },\n    {\n      field: 'dateOfBirth',\n      name: 'Date of Birth',\n      dataType: 'date',\n      render: date => formatDate(date, 'dobLong'),\n      sortable: true,\n    },\n    {\n      field: 'nationality',\n      name: 'Nationality',\n      render: countryCode => {\n        const country = store.getCountry(countryCode);\n        return `${country.flag} ${country.name}`;\n      },\n    },\n    {\n      field: 'online',\n      name: 'Online',\n      dataType: 'boolean',\n      render: online => {\n        const color = online ? 'success' : 'danger';\n        const label = online ? 'Online' : 'Offline';\n        return <EuiHealth color={color}>{label}</EuiHealth>;\n      },\n      sortable: true,\n    },\n  ];\n\n  const sorting = {\n    sort: {\n      field: 'dateOfBirth',\n      direction: 'desc',\n    },\n  };\n\n  return (\n    <EuiInMemoryTable\n      items={store.users}\n      columns={columns}\n      pagination={true}\n      sorting={sorting}\n    />\n  );\n};\n"