module.exports = "import React from 'react';\n\nimport {\n  EuiFlexGrid,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiIcon,\n  EuiPanel,\n  EuiText,\n  EuiCode,\n  EuiSpacer,\n  EuiButton,\n} from '../../../../src/components';\n\nimport reactSvg from '../../images/custom.svg';\n\nexport default () => (\n  <div>\n    <EuiFlexGrid columns={4}>\n      <EuiFlexItem className=\"guideDemo__icon\" style={{ width: '200px' }}>\n        <EuiPanel>\n          <EuiIcon type=\"logoElastic\" size=\"xl\" />\n          <EuiText size=\"s\">\n            <p>logoElastic</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n      <EuiFlexItem className=\"guideDemo__icon\" style={{ width: '200px' }}>\n        <EuiPanel>\n          <EuiIcon\n            type=\"https://upload.wikimedia.org/wikipedia/commons/0/02/SVG_logo.svg\"\n            size=\"xl\"\n          />\n          <EuiText size=\"s\">\n            <p>http://some.svg</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n      <EuiFlexItem className=\"guideDemo__icon\" style={{ width: '200px' }}>\n        <EuiPanel>\n          <EuiIcon type={reactSvg} size=\"xl\" />\n          <EuiText size=\"s\">\n            <p>{'{reactSvg}'}</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n    </EuiFlexGrid>\n\n    <EuiSpacer />\n\n    <EuiText>\n      <p>\n        Any component that utlizes <EuiCode>EuiIcon</EuiCode> can use custom\n        SVGs as well\n      </p>\n    </EuiText>\n\n    <EuiSpacer />\n\n    <EuiFlexGroup>\n      <EuiFlexItem grow={false}>\n        <EuiButton iconType=\"https://upload.wikimedia.org/wikipedia/commons/0/02/SVG_logo.svg\">\n          http://some.svg\n        </EuiButton>\n      </EuiFlexItem>\n      <EuiFlexItem grow={false}>\n        <EuiButton iconType={reactSvg}>{'{reactSvg}'}</EuiButton>\n      </EuiFlexItem>\n    </EuiFlexGroup>\n  </div>\n);\n"