import React, { Component, Fragment } from 'react';
import { EuiButtonEmpty } from '../../../../src/components/button';
import { EuiSelectable } from '../../../../src/components/selectable';
import { Options } from './data';

class _default extends Component {
  constructor(props) {
    super(props);
    this.state = {
      options: Options
    };
  }

  onChange = options => {
    this.setState({
      options
    });
  };

  render() {
    const {
      options
    } = this.state;
    return <Fragment>
        <EuiButtonEmpty onClick={() => {
        this.setState({
          options: Options.map(option => ({ ...option,
            checked: undefined
          }))
        });
      }}>
          Deselect all
        </EuiButtonEmpty>
        <EuiSelectable searchable searchProps={{
        'data-test-subj': 'selectableSearchHere'
      }} options={options} onChange={this.onChange}>
          {(list, search) => <Fragment>
              {search}
              {list}
            </Fragment>}
        </EuiSelectable>
      </Fragment>;
  }

}

_default.propTypes = {};
export { _default as default };