module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiStat,\n  EuiFlexItem,\n  EuiFlexGroup,\n  EuiPanel,\n  EuiIcon,\n  EuiSwitch,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isLoading: false,\n    };\n  }\n\n  onToggleChange = e => {\n    this.setState({ isLoading: e.target.checked });\n  };\n\n  render() {\n    return (\n      <div>\n        <EuiFlexGroup>\n          <EuiFlexItem>\n            <EuiPanel>\n              <EuiStat\n                title=\"8,888\"\n                description=\"Total widgets\"\n                textAlign=\"right\"\n                isLoading={this.state.isLoading}>\n                <EuiIcon type=\"empty\" />\n              </EuiStat>\n            </EuiPanel>\n          </EuiFlexItem>\n          <EuiFlexItem>\n            <EuiPanel>\n              <EuiStat\n                title=\"2,000\"\n                description=\"Pending widgets\"\n                titleColor=\"accent\"\n                textAlign=\"right\"\n                isLoading={this.state.isLoading}>\n                <EuiIcon type=\"clock\" color=\"accent\" />\n              </EuiStat>\n            </EuiPanel>\n          </EuiFlexItem>\n          <EuiFlexItem>\n            <EuiPanel>\n              <EuiStat\n                title=\"6,800\"\n                description=\"Success widgets\"\n                titleColor=\"secondary\"\n                textAlign=\"right\"\n                isLoading={this.state.isLoading}>\n                <EuiIcon type=\"check\" color=\"secondary\" />\n              </EuiStat>\n            </EuiPanel>\n          </EuiFlexItem>\n          <EuiFlexItem>\n            <EuiPanel>\n              <EuiStat\n                title=\"88\"\n                description=\"Error widgets\"\n                titleColor=\"danger\"\n                textAlign=\"right\"\n                isLoading={this.state.isLoading}>\n                <EuiIcon type=\"alert\" color=\"danger\" />\n              </EuiStat>\n            </EuiPanel>\n          </EuiFlexItem>\n        </EuiFlexGroup>\n        <EuiSpacer />\n        <EuiSwitch\n          label=\"Show as loading\"\n          checked={this.state.isLoading}\n          onChange={this.onToggleChange}\n        />\n      </div>\n    );\n  }\n}\n"