module.exports = "import React, { Component, Fragment } from 'react';\n\nimport { EuiRange, EuiSpacer, EuiDualRange } from '../../../../src/components';\n\nimport { DisplayToggles } from '../form_controls/display_toggles';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.levels = [\n      {\n        min: 0,\n        max: 20,\n        color: 'danger',\n      },\n      {\n        min: 20,\n        max: 100,\n        color: 'success',\n      },\n    ];\n\n    this.state = {\n      value: '20',\n      dualValue: [20, 100],\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  onDualChange = value => {\n    this.setState({\n      dualValue: value,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <DisplayToggles canAppend canPrepend>\n          <EuiRange\n            id={makeId()}\n            value={this.state.value}\n            onChange={this.onChange}\n            showInput=\"inputWithPopover\"\n            showLabels\n          />\n        </DisplayToggles>\n\n        <EuiSpacer size=\"xl\" />\n\n        <DisplayToggles canAppend canPrepend canLoading={false}>\n          <EuiDualRange\n            id={makeId()}\n            value={this.state.dualValue}\n            onChange={this.onDualChange}\n            showInput=\"inputWithPopover\"\n            showLabels\n            levels={this.levels}\n          />\n        </DisplayToggles>\n      </Fragment>\n    );\n  }\n}\n"