module.exports = "import React, { Component } from 'react';\n\nimport { EuiPopover, EuiButton } from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n    };\n  }\n\n  onButtonClick() {\n    this.setState({\n      isPopoverOpen: !this.state.isPopoverOpen,\n    });\n  }\n\n  closePopover() {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  }\n\n  render() {\n    return (\n      <EuiPopover\n        id=\"popoverPanelClassName\"\n        ownFocus\n        button={\n          <EuiButton\n            iconType=\"arrowDown\"\n            iconSide=\"right\"\n            onClick={this.onButtonClick.bind(this)}>\n            Turn padding off and apply a custom class\n          </EuiButton>\n        }\n        isOpen={this.state.isPopoverOpen}\n        closePopover={this.closePopover.bind(this)}\n        panelClassName=\"yourClassNameHere\"\n        panelPaddingSize=\"none\">\n        This should have no padding, and if you inspect, also a custom class.\n      </EuiPopover>\n    );\n  }\n}\n"