module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiBadge,\n  EuiHighlight,\n  EuiSpacer,\n  EuiTextColor,\n  EuiSwitch,\n} from '../../../../src/components';\nimport { EuiSelectable } from '../../../../src/components/selectable';\nimport { createDataStore } from '../tables/data_store';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.countries = createDataStore().countries.map(country => {\n      return {\n        id: country.code,\n        label: `${country.name}`,\n        prepend: country.flag,\n        append: <EuiBadge>{country.code}</EuiBadge>,\n      };\n    });\n\n    this.countries.unshift({\n      label: 'Country options',\n      isGroupLabel: true,\n    });\n\n    this.state = {\n      options: this.countries,\n      useCustomContent: false,\n    };\n  }\n\n  onChange = options => {\n    this.setState({\n      options,\n    });\n  };\n\n  onCustom = e => {\n    this.setState({\n      useCustomContent: e.currentTarget.checked,\n    });\n  };\n\n  renderCountryOption = (option, searchValue) => {\n    return (\n      <Fragment>\n        <EuiHighlight search={searchValue}>{option.label}</EuiHighlight>\n        <br />\n        <EuiTextColor color=\"subdued\">\n          <small>I am secondary content, I am!</small>\n        </EuiTextColor>\n      </Fragment>\n    );\n  };\n\n  render() {\n    const { options, useCustomContent } = this.state;\n\n    let customProps;\n    if (useCustomContent) {\n      customProps = {\n        height: 240,\n        renderOption: this.renderCountryOption,\n        listProps: {\n          rowHeight: 50,\n          showIcons: false,\n        },\n      };\n    }\n\n    return (\n      <Fragment>\n        <EuiSwitch\n          label=\"Custom content with no icons\"\n          checked={useCustomContent}\n          onChange={this.onCustom}\n        />\n\n        <EuiSpacer />\n\n        <EuiSelectable\n          searchable\n          options={options}\n          onChange={this.onChange}\n          {...customProps}>\n          {(list, search) => (\n            <Fragment>\n              {search}\n              {list}\n            </Fragment>\n          )}\n        </EuiSelectable>\n      </Fragment>\n    );\n  }\n}\n"