module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiPage,\n  EuiPageBody,\n  EuiPageHeader,\n  EuiPageHeaderSection,\n  EuiPageContent,\n  EuiPageContentHeader,\n  EuiPageContentHeaderSection,\n  EuiPageContentBody,\n  EuiHeader,\n  EuiHeaderSection,\n  EuiHeaderSectionItem,\n  EuiHeaderSectionItemButton,\n  EuiHeaderBreadcrumbs,\n  EuiHeaderLogo,\n  EuiIcon,\n  EuiImage,\n  EuiTitle,\n  EuiNavDrawerGroup,\n  EuiNavDrawer,\n  EuiHorizontalRule,\n  EuiShowFor,\n  EuiFocusTrap,\n  EuiButton,\n} from '../../../../src/components';\n\nimport { keyCodes } from '../../../../src/services';\n\nimport HeaderUserMenu from '../header/header_user_menu';\nimport HeaderSpacesMenu from '../header/header_spaces_menu';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isFullScreen: false,\n    };\n\n    const faveExtraAction = {\n      color: 'subdued',\n      iconType: 'starEmpty',\n      iconSize: 's',\n      'aria-label': 'Add to favorites',\n    };\n\n    const pinExtraAction = {\n      color: 'subdued',\n      iconType: 'pin',\n      iconSize: 's',\n    };\n\n    const pinExtraActionFn = val => {\n      pinExtraAction['aria-label'] = `Pin ${val} to top`;\n      return pinExtraAction;\n    };\n\n    this.topLinks = [\n      {\n        label: 'Recently viewed',\n        iconType: 'clock',\n        flyoutMenu: {\n          title: 'Recent items',\n          listItems: [\n            {\n              label: 'My dashboard',\n              href: '#/layout/nav-drawer',\n              iconType: 'dashboardApp',\n              extraAction: faveExtraAction,\n            },\n            {\n              label: 'Workpad with title that wraps',\n              href: '#/layout/nav-drawer',\n              iconType: 'canvasApp',\n              extraAction: faveExtraAction,\n            },\n            {\n              label: 'My logs',\n              href: '#/layout/nav-drawer',\n              iconType: 'loggingApp',\n              'aria-label': 'This is an alternate aria-label',\n              extraAction: faveExtraAction,\n            },\n          ],\n        },\n      },\n      {\n        label: 'Favorites',\n        iconType: 'starEmpty',\n        flyoutMenu: {\n          title: 'Favorite items',\n          listItems: [\n            {\n              label: 'My workpad',\n              href: '#/layout/nav-drawer',\n              iconType: 'canvasApp',\n              extraAction: {\n                color: 'subdued',\n                iconType: 'starFilled',\n                iconSize: 's',\n                'aria-label': 'Remove from favorites',\n                alwaysShow: true,\n              },\n            },\n            {\n              label: 'My logs',\n              href: '#/layout/nav-drawer',\n              iconType: 'loggingApp',\n              extraAction: {\n                color: 'subdued',\n                iconType: 'starFilled',\n                iconSize: 's',\n                'aria-label': 'Remove from favorites',\n                alwaysShow: true,\n              },\n            },\n          ],\n        },\n      },\n    ];\n\n    this.exploreLinks = [\n      {\n        label: 'Canvas',\n        href: '#/layout/nav-drawer',\n        iconType: 'canvasApp',\n        isActive: true,\n        extraAction: {\n          ...pinExtraActionFn('Canvas'),\n          alwaysShow: true,\n        },\n      },\n      {\n        label: 'Discover',\n        href: '#/layout/nav-drawer',\n        iconType: 'discoverApp',\n        extraAction: { ...pinExtraActionFn('Discover') },\n      },\n      {\n        label: 'Visualize',\n        href: '#/layout/nav-drawer',\n        iconType: 'visualizeApp',\n        extraAction: { ...pinExtraActionFn('Visualize') },\n      },\n      {\n        label: 'Dashboard',\n        href: '#/layout/nav-drawer',\n        iconType: 'dashboardApp',\n        extraAction: { ...pinExtraActionFn('Dashboard') },\n      },\n      {\n        label: 'Machine learning',\n        href: '#/layout/nav-drawer',\n        iconType: 'machineLearningApp',\n        extraAction: { ...pinExtraActionFn('Machine learning') },\n      },\n      {\n        label: 'Custom Plugin (no icon)',\n        href: '#/layout/nav-drawer',\n        extraAction: { ...pinExtraActionFn('Custom Plugin') },\n      },\n      {\n        label: 'Nature Plugin (image as icon)',\n        href: '#/layout/nav-drawer',\n        extraAction: { ...pinExtraActionFn('Nature Plugin') },\n        icon: (\n          <EuiImage\n            size=\"s\"\n            alt=\"Random nature image\"\n            url=\"https://source.unsplash.com/300x300/?Nature\"\n          />\n        ),\n      },\n    ];\n\n    this.solutionsLinks = [\n      {\n        label: 'APM',\n        href: '#/layout/nav-drawer',\n        iconType: 'apmApp',\n        extraAction: { ...pinExtraActionFn('APM') },\n      },\n      {\n        label: 'Infrastructure',\n        href: '#/layout/nav-drawer',\n        iconType: 'infraApp',\n        extraAction: { ...pinExtraActionFn('Infrastructure') },\n      },\n      {\n        label: 'Log viewer',\n        href: '#/layout/nav-drawer',\n        iconType: 'loggingApp',\n        extraAction: { ...pinExtraActionFn('Log viewer') },\n      },\n      {\n        label: 'Uptime',\n        href: '#/layout/nav-drawer',\n        iconType: 'upgradeAssistantApp',\n        extraAction: { ...pinExtraActionFn('Uptime') },\n      },\n      {\n        label: 'Maps',\n        href: '#/layout/nav-drawer',\n        iconType: 'gisApp',\n        extraAction: { ...pinExtraActionFn('Maps') },\n      },\n      {\n        label: 'SIEM',\n        href: '#/layout/nav-drawer',\n        iconType: 'securityAnalyticsApp',\n        extraAction: { ...pinExtraActionFn('SIEM') },\n      },\n    ];\n\n    this.adminLinks = [\n      {\n        label: 'Admin',\n        iconType: 'managementApp',\n        flyoutMenu: {\n          title: 'Tools and settings',\n          listItems: [\n            {\n              label: 'Dev tools',\n              href: '#/layout/nav-drawer',\n              iconType: 'devToolsApp',\n              extraAction: {\n                color: 'subdued',\n                iconType: 'starEmpty',\n                iconSize: 's',\n                'aria-label': 'Add to favorites',\n              },\n            },\n            {\n              label: 'Stack Monitoring',\n              href: '#/layout/nav-drawer',\n              iconType: 'monitoringApp',\n              extraAction: {\n                color: 'subdued',\n                iconType: 'starEmpty',\n                iconSize: 's',\n                'aria-label': 'Add to favorites',\n              },\n            },\n            {\n              label: 'Stack Management',\n              href: '#/layout/nav-drawer',\n              iconType: 'managementApp',\n              extraAction: {\n                color: 'subdued',\n                iconType: 'starEmpty',\n                iconSize: 's',\n                'aria-label': 'Add to favorites',\n              },\n            },\n          ],\n        },\n      },\n    ];\n  }\n\n  onKeyDown = event => {\n    if (event.keyCode === keyCodes.ESCAPE) {\n      event.preventDefault();\n      event.stopPropagation();\n      this.closeFullScreen();\n    }\n  };\n\n  toggleFullScreen = () => {\n    this.setState(prevState => ({\n      isFullScreen: !prevState.isFullScreen,\n    }));\n  };\n\n  closeFullScreen = () => {\n    this.setState({\n      isFullScreen: false,\n    });\n  };\n\n  renderLogo() {\n    return (\n      <EuiHeaderLogo\n        iconType=\"logoKibana\"\n        href=\"#/layout/nav-drawer\"\n        aria-label=\"Goes to home\"\n      />\n    );\n  }\n\n  renderMenuTrigger() {\n    return (\n      <EuiHeaderSectionItemButton\n        aria-label=\"Open nav\"\n        onClick={() => this.navDrawerRef.toggleOpen()}>\n        <EuiIcon type=\"apps\" href=\"#\" size=\"m\" />\n      </EuiHeaderSectionItemButton>\n    );\n  }\n\n  renderBreadcrumbs() {\n    const breadcrumbs = [\n      {\n        text: 'Management',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked management');\n        },\n        'data-test-subj': 'breadcrumbsAnimals',\n        className: 'customClass',\n      },\n      {\n        text: 'Truncation test is here for a really long item',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked truncation test');\n        },\n      },\n      {\n        text: 'hidden',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked hidden');\n        },\n      },\n      {\n        text: 'Users',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked users');\n        },\n      },\n      {\n        text: 'Create',\n      },\n    ];\n\n    return <EuiHeaderBreadcrumbs breadcrumbs={breadcrumbs} />;\n  }\n\n  setNavDrawerRef = ref => (this.navDrawerRef = ref);\n\n  render() {\n    let fullScreenDisplay;\n\n    if (this.state.isFullScreen) {\n      fullScreenDisplay = (\n        <EuiFocusTrap>\n          <div\n            style={{\n              position: 'fixed',\n              top: 0,\n              left: 0,\n              height: '100%',\n              width: '100%',\n            }}\n            onKeyDown={this.onKeyDown}>\n            <EuiHeader>\n              <EuiHeaderSection grow={false}>\n                <EuiShowFor sizes={['xs', 's']}>\n                  <EuiHeaderSectionItem border=\"right\">\n                    {this.renderMenuTrigger()}\n                  </EuiHeaderSectionItem>\n                </EuiShowFor>\n                <EuiHeaderSectionItem border=\"right\">\n                  {this.renderLogo()}\n                </EuiHeaderSectionItem>\n                <EuiHeaderSectionItem border=\"right\">\n                  <HeaderSpacesMenu />\n                </EuiHeaderSectionItem>\n              </EuiHeaderSection>\n\n              {this.renderBreadcrumbs()}\n\n              <EuiHeaderSection side=\"right\">\n                <EuiHeaderSectionItem>\n                  <HeaderUserMenu />\n                </EuiHeaderSectionItem>\n              </EuiHeaderSection>\n            </EuiHeader>\n            <EuiNavDrawer ref={this.setNavDrawerRef}>\n              <EuiNavDrawerGroup listItems={this.topLinks} />\n              <EuiHorizontalRule margin=\"none\" />\n              <EuiNavDrawerGroup listItems={this.exploreLinks} />\n              <EuiHorizontalRule margin=\"none\" />\n              <EuiNavDrawerGroup listItems={this.solutionsLinks} />\n              <EuiHorizontalRule margin=\"none\" />\n              <EuiNavDrawerGroup listItems={this.adminLinks} />\n            </EuiNavDrawer>\n            <EuiPage className=\"euiNavDrawerPage\">\n              <EuiPageBody className=\"euiNavDrawerPage__pageBody\">\n                <EuiPageHeader>\n                  <EuiPageHeaderSection>\n                    <EuiTitle size=\"l\">\n                      <h1>Page title</h1>\n                    </EuiTitle>\n                  </EuiPageHeaderSection>\n                </EuiPageHeader>\n                <EuiPageContent>\n                  <EuiPageContentHeader>\n                    <EuiPageContentHeaderSection>\n                      <EuiTitle>\n                        <h2>Content title</h2>\n                      </EuiTitle>\n                    </EuiPageContentHeaderSection>\n                  </EuiPageContentHeader>\n                  <EuiPageContentBody>\n                    <EuiButton\n                      fill\n                      onClick={this.toggleFullScreen}\n                      iconType=\"exit\"\n                      aria-label=\"Exit fullscreen demo\">\n                      Exit fullscreen demo\n                    </EuiButton>\n                  </EuiPageContentBody>\n                </EuiPageContent>\n              </EuiPageBody>\n            </EuiPage>\n          </div>\n        </EuiFocusTrap>\n      );\n    }\n    return (\n      <Fragment>\n        <EuiButton\n          onClick={this.toggleFullScreen}\n          iconType=\"fullScreen\"\n          aria-label=\"Show fullscreen demo\">\n          Show fullscreen demo\n        </EuiButton>\n\n        {/*\n          If the below fullScreen code renders, it actually attaches to the body because of\n          EuiOverlayMask's React portal usage.\n        */}\n\n        {fullScreenDisplay}\n      </Fragment>\n    );\n  }\n}\n"